/// <summary>
///     Retrieves the report header title.
/// </summary>
/// <returns>
///     The report header title.
/// </returns>
protected str documentTitle()
{
    str documentTitle = next documentTitle();
    boolean isCreditNote = custInvoiceJour.InvoiceAmount < 0 || (custInvoiceJour.InvoiceAmount == 0 && custInvoiceJour.Qty < 0);
    boolean avaIsEDI = custInvoiceJour.AVAEDITransfer;
    CustLanguageId languageId;
    CustParameters custParameters = CustParameters::find();
    CompanyInfo companyInfo = CompanyInfo::find();
    Label avaLabel = new Label(SalesInvoiceController::getCustLanguageId(custInvoiceJour));

    languageId = SalesInvoiceController::getCustLanguageId(custInvoiceJour);
    documentTitle = '';

    if (!isCreditNote)
    {
        if(avaIsEDI)
        {
            if (salesInvoiceContract.parmPrintCopyOriginal() == PrintCopyOriginal::Copy)
            {
                documentTitle = avaLabel.extractString("@NDX:NXASalesInvoiceEDICopy");
            }
            else
            {
                documentTitle = avaLabel.extractString("@NDX:NXASalesInvoiceEDI");
            }
        }
        else
        {
            if (salesInvoiceContract.parmPrintCopyOriginal() == PrintCopyOriginal::Copy)
            {
                documentTitle = avaLabel.extractString("@NDX:NXASalesInvoiceCopy");
            }
            else
            {
                documentTitle = avaLabel.extractString("@NDX:NXASalesInvoice");
            }
        }
    }
    else
    {
        if(avaIsEDI)
        {
            if (salesInvoiceContract.parmPrintCopyOriginal() == PrintCopyOriginal::Copy)
            {
                documentTitle = avaLabel.extractString("@NDX:NXAEDICreditNoteCopy");
            }
            else
            {
                documentTitle = avaLabel.extractString("@NDX:NXAEDICreditNote");
            }
        }
        else
        {
            if (salesInvoiceContract.parmPrintCopyOriginal() == PrintCopyOriginal::Copy)
            {
                documentTitle = avaLabel.extractString("@NDX:NXACreditNoteCopy");
            }
            else
            {
                documentTitle = avaLabel.extractString("@NDX:NXACreditNote");
            }
        }
    }

    if(custInvoiceJour.isProforma())
    {
        documentTitle = strFmt(avaLabel.extractString("@NDX:NXAProFormaSpacing"), avaLabel.extractString("@NDX:NXAProforma"), documentTitle);
    }

    return documentTitle;
}
